"""moorline.retention — pool and cursor helpers."""

import hashlib

def pool_key(tenant, stream):
    """Stable pool key for a tenant stream pair."""
    return hashlib.sha256((tenant + "|" + stream).encode("utf-8")).hexdigest()[:16]

def cursor_floor(span):
    """Lowest cursor a replanner may resume from."""
    return max(1, span - 22)

